CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,username VARCHAR(80) NOT NULL UNIQUE,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('ADMIN','DIREKTUR','SOLVER') NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,archived_at DATETIME NULL) ENGINE=InnoDB;
CREATE TABLE clients (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,pic_name VARCHAR(120) NOT NULL,whatsapp VARCHAR(40),email VARCHAR(190),address TEXT,city VARCHAR(100),npwp VARCHAR(60),nib VARCHAR(60),notes TEXT,status VARCHAR(30) NOT NULL DEFAULT 'Aktif',created_by BIGINT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,archived_at DATETIME NULL,INDEX(name),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE services (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL UNIQUE,category VARCHAR(100) NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,archived_at DATETIME NULL) ENGINE=InnoDB;
CREATE TABLE service_milestones (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,service_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,sort_order INT NOT NULL,weight INT NOT NULL DEFAULT 1,active TINYINT(1) NOT NULL DEFAULT 1,FOREIGN KEY(service_id) REFERENCES services(id),INDEX(service_id,sort_order)) ENGINE=InnoDB;
CREATE TABLE projects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) UNIQUE,client_id BIGINT UNSIGNED NOT NULL,service_id BIGINT UNSIGNED NOT NULL,solver_id BIGINT UNSIGNED NOT NULL,crm_lead_id VARCHAR(100),crm_client_id VARCHAR(100),source VARCHAR(100),tanggal_mulai DATE NOT NULL,project_active_at DATETIME NOT NULL,target_selesai DATE,current_milestone_id BIGINT UNSIGNED NULL,progress_percentage TINYINT UNSIGNED NOT NULL DEFAULT 0,status ENUM('Baru','Aktif','Proses','Menunggu','Tertunda','Terbit','Selesai','Dibatalkan') NOT NULL DEFAULT 'Baru',waiting_status ENUM('Tidak Ada Kendala','Menunggu Klien','Menunggu Instansi','Menunggu Internal','Menunggu Solver','Lainnya') NOT NULL DEFAULT 'Tidak Ada Kendala',next_action TEXT,next_action_due_date DATE,last_progress_update DATETIME,tanggal_terbit DATE,tanggal_selesai DATE,nomor_izin VARCHAR(150),notes TEXT,closed_at DATETIME,created_by BIGINT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,archived_at DATETIME NULL,FOREIGN KEY(client_id) REFERENCES clients(id),FOREIGN KEY(service_id) REFERENCES services(id),FOREIGN KEY(solver_id) REFERENCES users(id),FOREIGN KEY(created_by) REFERENCES users(id),INDEX(solver_id),INDEX(client_id),INDEX(service_id),INDEX(status),INDEX(waiting_status),INDEX(last_progress_update)) ENGINE=InnoDB;
CREATE TABLE project_milestones (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,sort_order INT NOT NULL,weight INT NOT NULL DEFAULT 1,state ENUM('Belum','Proses','Selesai') NOT NULL DEFAULT 'Belum',completed_at DATETIME,FOREIGN KEY(project_id) REFERENCES projects(id),INDEX(project_id,sort_order)) ENGINE=InnoDB;
ALTER TABLE projects ADD CONSTRAINT fk_current_milestone FOREIGN KEY(current_milestone_id) REFERENCES project_milestones(id);
CREATE TABLE project_solver_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,old_solver_id BIGINT UNSIGNED NOT NULL,new_solver_id BIGINT UNSIGNED NOT NULL,changed_by BIGINT UNSIGNED NOT NULL,reason TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id),FOREIGN KEY(old_solver_id) REFERENCES users(id),FOREIGN KEY(new_solver_id) REFERENCES users(id),FOREIGN KEY(changed_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE progress_updates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,milestone_id BIGINT UNSIGNED,status VARCHAR(30) NOT NULL,waiting_status VARCHAR(40) NOT NULL,development TEXT NOT NULL,obstacle TEXT,next_action TEXT,next_action_due_date DATE,internal_notes TEXT,update_at DATETIME NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id),FOREIGN KEY(milestone_id) REFERENCES project_milestones(id),FOREIGN KEY(created_by) REFERENCES users(id),INDEX(project_id,update_at)) ENGINE=InnoDB;
CREATE TABLE client_updates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,progress_update_id BIGINT UNSIGNED NOT NULL,communicated_at DATETIME NOT NULL,method ENUM('WhatsApp','Telepon','Email','Meeting Online','Meeting Offline','Lainnya') NOT NULL,summary TEXT NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id),FOREIGN KEY(progress_update_id) REFERENCES progress_updates(id),FOREIGN KEY(created_by) REFERENCES users(id),INDEX(project_id,communicated_at)) ENGINE=InnoDB;
CREATE TABLE attachments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,original_name VARCHAR(255) NOT NULL,internal_name VARCHAR(100) NOT NULL UNIQUE,category VARCHAR(50) NOT NULL,uploader_id BIGINT UNSIGNED NOT NULL,size_bytes BIGINT UNSIGNED NOT NULL,mime_type VARCHAR(150) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id),FOREIGN KEY(uploader_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,project_id BIGINT UNSIGNED,title VARCHAR(200) NOT NULL,body TEXT,read_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(project_id) REFERENCES projects(id),INDEX(user_id,read_at)) ENGINE=InnoDB;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,object_type VARCHAR(80) NOT NULL,object_id BIGINT UNSIGNED NULL,description TEXT,ip_address VARCHAR(45),user_agent VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX(created_at),INDEX(object_type,object_id)) ENGINE=InnoDB;
CREATE TABLE settings (name VARCHAR(100) PRIMARY KEY,value TEXT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,identity VARCHAR(190) NOT NULL,ip_address VARCHAR(45) NOT NULL,attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(identity,ip_address,attempted_at)) ENGINE=InnoDB;
